-- ล้างชื่อทีม/ภาค: ช่องว่างหัวท้าย ช่องว่างซ้อน อักษรมองไม่เห็น (zero-width) — กติกาเดียวกับ backend/src/utils/names.ts
-- ขอบเขตหัวหน้าภาคเทียบชื่อแบบตรงทุกตัวอักษร ชื่อที่หน้าจอเห็นเหมือนกันแต่ข้างในต่างกัน
-- ทำให้หัวหน้าภาคที่ติ๊กทีมไว้แล้วไม่เห็นใบงาน และใบขึ้น "ไม่มีคนรับ" (เจอจริง ต.ค. 69)
-- ไม่แตะ TeamDayPlan (unique วัน+ทีม — แผนย้อนหลังชนกันได้) และ TeamGroup.name (unique)

UPDATE "Branch" SET "zone" = NULLIF(btrim(regexp_replace(regexp_replace(normalize("zone", NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '') WHERE "zone" IS DISTINCT FROM NULLIF(btrim(regexp_replace(regexp_replace(normalize("zone", NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '');
UPDATE "Branch" SET "pmTeam" = NULLIF(btrim(regexp_replace(regexp_replace(normalize("pmTeam", NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '') WHERE "pmTeam" IS DISTINCT FROM NULLIF(btrim(regexp_replace(regexp_replace(normalize("pmTeam", NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '');
UPDATE "Branch" SET "region" = NULLIF(btrim(regexp_replace(regexp_replace(normalize("region", NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '') WHERE "region" IS DISTINCT FROM NULLIF(btrim(regexp_replace(regexp_replace(normalize("region", NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '');
UPDATE "User" SET "team" = NULLIF(btrim(regexp_replace(regexp_replace(normalize("team", NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '') WHERE "team" IS DISTINCT FROM NULLIF(btrim(regexp_replace(regexp_replace(normalize("team", NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '');
UPDATE "User" SET "region" = NULLIF(btrim(regexp_replace(regexp_replace(normalize("region", NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '') WHERE "region" IS DISTINCT FROM NULLIF(btrim(regexp_replace(regexp_replace(normalize("region", NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '');
UPDATE "User" SET "supervisedTeams" = ARRAY(SELECT DISTINCT v FROM (SELECT NULLIF(btrim(regexp_replace(regexp_replace(normalize(x, NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '') AS v FROM unnest("supervisedTeams") AS u(x)) s WHERE v IS NOT NULL)
  WHERE EXISTS (SELECT 1 FROM unnest("supervisedTeams") AS u(x) WHERE x IS DISTINCT FROM NULLIF(btrim(regexp_replace(regexp_replace(normalize(x, NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), ''));
UPDATE "WorkOrder" SET "assignedTeam" = NULLIF(btrim(regexp_replace(regexp_replace(normalize("assignedTeam", NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '') WHERE "assignedTeam" IS DISTINCT FROM NULLIF(btrim(regexp_replace(regexp_replace(normalize("assignedTeam", NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '');
UPDATE "TeamGroup" SET "covers" = ARRAY(SELECT DISTINCT v FROM (SELECT NULLIF(btrim(regexp_replace(regexp_replace(normalize(x, NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '') AS v FROM unnest("covers") AS u(x)) s WHERE v IS NOT NULL)
  WHERE EXISTS (SELECT 1 FROM unnest("covers") AS u(x) WHERE x IS DISTINCT FROM NULLIF(btrim(regexp_replace(regexp_replace(normalize(x, NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), ''));
UPDATE "BranchTeamMove" SET "toTeam" = NULLIF(btrim(regexp_replace(regexp_replace(normalize("toTeam", NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '') WHERE NULLIF(btrim(regexp_replace(regexp_replace(normalize("toTeam", NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '') IS NOT NULL AND "toTeam" <> NULLIF(btrim(regexp_replace(regexp_replace(normalize("toTeam", NFC), '[\u200B-\u200D\u2060\uFEFF]', '', 'g'), '[\s\u00A0]+', ' ', 'g')), '');
